INSERT INTO `m_feedback` VALUES
(52,165,'Avaliação da Formação','A sua opinião é fundamental para melhorarmos as nossas formações.',1,1,1,0,1,'','',0,1,0,0,1778098503,1);
INSERT INTO `m_feedback_item` VALUES
(511,52,0,'Os conteúdos abordados foram relevantes para as suas responsabilidades profissionais?','','r>>>>>1 (Nada Relevante)|2|3|4|5 (Totalmente Relevante)<<<<<1','multichoice',1,1,1,0,'',''),
(512,52,0,'O equilíbrio entre a componente teórica e a componente prática foi adequado?','','r>>>>>1 (Inadequado)|2|3|4|5 (Muito Adequado)<<<<<1','multichoice',1,2,1,0,'',''),
(513,52,0,'O formador demonstrou domínio técnico e segurança nos temas apresentados?','','r>>>>>1 (Fraco)|2|3|4|5 (Excelente)<<<<<1','multichoice',1,3,1,0,'',''),
(514,52,0,'A capacidade de comunicação e o dinamismo do formador facilitaram a aprendizagem?','','r>>>>>1 (Discordo Totalmente)|2|3|4|5 (Concordo Totalmente)<<<<<1','multichoice',1,4,1,0,'',''),
(515,52,0,'Considera que conseguirá aplicar os conhecimentos adquiridos no seu quotidiano profissional?','','r>>>>>1 (Improvável)|2|3|4|5 (Muito Provável)<<<<<1','multichoice',1,5,1,0,'',''),
(516,52,0,'As tecnologias e ferramentas utilizadas (plataformas, software) foram eficazes para o sucesso da formação?','','r>>>>>1 (Pouco Eficazes)|2|3|4|5 (Muito Eficazes)<<<<<1','multichoice',1,6,1,0,'',''),
(517,52,0,'Como avalia o impacto desta formação na sua produtividade ou qualidade de trabalho?','','r>>>>>1 (Baixo Impacto)|2|3|4|5 (Elevado Impacto)<<<<<1','multichoice',1,7,1,0,'',''),
(518,52,0,'Identifique o ponto forte ou o aspeto mais valioso desta formação.','','40|5','textarea',0,8,0,0,'',''),
(519,52,0,'Que melhorias ou ajustes recomendaria para futuras edições deste programa?','','40|5','textarea',0,9,0,0,'',''),
(520,52,0,'Indique outros temas de formação que considere relevantes para o seu desenvolvimento na empresa.','','40|5','textarea',0,10,0,0,'','');
