INSERT INTO `m_quiz` VALUES
(136,148,'🎯 Avaliação Final - PowerEdge R750','Quiz de avaliação final do curso de Instalação e Manutenção do Dell PowerEdge R750. Contém 10 questões aleatórias sorteadas de um banco de 20, abrangendo todos os tópicos: visão geral, configuração, iDRAC, procedimentos de hardware, diagnóstico, jumpers, TPM, risers, backplane, fontes, etc. O tempo limite é de 30 minutos. São permitidas 3 tentativas. A nota mínima de aprovação é 15 pontos (75%).',1,0,0,1800,'autoabandon',0,'deferredfeedback',0,0,0,1,2,-1,4368,4368,4368,4368,0,4368,0,0,1,'free',1,10.00000,20.00000,1777460047,1777460047,'','','-',0,0,0,0,0,0,0,NULL),
(137,149,'🎯 Avaliação Final de Competências','Este exame valida o seu conhecimento sobre a operação segura, especificações técnicas e manutenção da Bimby® TM5 baseando-se estritamente no manual de instruções.',1,0,0,1800,'autoabandon',0,'deferredfeedback',0,0,0,1,2,-1,4368,4368,4368,4368,0,4368,0,0,1,'free',1,10.00000,20.00000,1777461592,1777461592,'','','-',0,0,0,0,0,0,0,NULL),
(138,150,'🎯 Avaliação Final de Competências','Este exame valida o seu conhecimento sobre a operação segura, especificações técnicas e manutenção da Bimby® TM5 baseando-se estritamente no manual de instruções.',1,0,0,1800,'autoabandon',0,'deferredfeedback',0,0,0,1,2,-1,4368,4368,4368,4368,0,4368,0,0,1,'free',1,10.00000,20.00000,1777461694,1777461694,'','','-',0,0,0,0,0,0,0,NULL),
